\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath,amssymb,amsthm,booktabs,array,microtype,hyperref}
\newtheorem{theorem}{Theorem}[section]
\newtheorem{corollary}[theorem]{Corollary}
\newtheorem{definition}[theorem]{Definition}
\newtheorem{remark}[theorem]{Remark}
\title{Molecular Computation Under Explicit Resource Accounting:\\Universality, Description Volume, and Preparation-Limited Parallelism}
\author{Aristotle}
\date{July 30, 2026}

\begin{document}
\maketitle

\begin{abstract}
Chemical reaction networks provide a minimal language in which molecular populations represent data and reactions represent state transitions. We give a self-contained account of computational universality, physical description capacity, and the end-to-end value of molecular parallelism. Any deterministic transition system is compiled into a unary reaction network whose one-hot population follows every finite execution trace exactly. Under discrete stochastic mass-action kinetics, the transition enabled at a one-hot source has propensity equal to its assigned rate; decoded outputs and fixed halting states are preserved. For a medium with positive integer capacity $b$ bits per volume unit, the exact minimum integer volume for a $K$-bit description is $\lceil K/b\rceil$. Finally, if each of $N$ candidates costs $c\geq1$ units to prepare, sequential elapsed time $(c+1)N$ is at most twice ideal molecular elapsed time $cN+1$, even when $N=2^n$. The results distinguish mathematical consequences of explicit models from empirical claims about DNA density and reaction throughput.
\end{abstract}

\section{Introduction}
Molecular computation replaces electronic gates with transformations among molecular species. Its appeal rests on density, concurrency, and programmability: molecules are small, many reactions can proceed simultaneously, and carefully selected reactions can represent symbolic transitions. These facts motivate several claims that must be separated. A logical universality claim asks whether reaction rules reproduce arbitrary computation. A capacity claim asks how much reliable information fits in a volume. A throughput claim asks how many correct transitions occur per unit time. A complexity claim asks whether concurrency changes end-to-end asymptotic cost.

We use transparent models. Computation consists of discrete populations and integer-stoichiometric reactions. A deterministic transition is compiled using one species per configuration. Kinetic availability follows stochastic mass-action propensity with falling factorials. Storage has a fixed reliable bit capacity per integer volume unit. Exhaustive search is charged for both candidate preparation and testing.

Four conclusions follow. Reaction networks exactly simulate every finite trace of an arbitrary deterministic machine. Unary compiled reactions have their assigned mass-action propensity at one-hot source states. Minimum description volume is ceiling division by bit density. Perfect parallel testing gives no exponential end-to-end speedup if each candidate must be separately prepared at positive linear cost.

The qualifications are substantive. A compilation with one species per configuration may be an infinite mathematical schema, not a manufacturable device. Likewise, if a device stores $10^{18}$ reliable bits, it has $2^{10^{18}}$ Boolean states; and if it performs $10^{15}$ correct operations in one second, its rate is $10^{15}$ operations per second. The antecedents are experimental claims, not consequences of abstract counting.

\section{Reaction-network model}
Let $I$ be a set of molecular species.

\begin{definition}[Population and reaction]
A population is a function $x:I\to\mathbb N$, where $x(i)$ counts species $i$. A reaction $R$ consists of finitely supported reactant and product functions $r_R,p_R:I\to\mathbb N$, written
\[
 \sum_{i\in I}r_R(i)S_i\longrightarrow \sum_{i\in I}p_R(i)S_i.
\]
It is enabled at $x$ when $r_R(i)\leq x(i)$ for every $i$. Its firing produces $x'(i)=x(i)-r_R(i)+p_R(i)$.
\end{definition}

\begin{definition}[One-hot population]
For $q\in I$, the one-hot population $e_q$ is given by $e_q(q)=1$ and $e_q(i)=0$ for $i\neq q$.
\end{definition}

Let $Q$ be a configuration space and $T:Q\to Q$ a deterministic transition function. Associate species $S_q$ with $q\in Q$ and include the unary reaction
\[
 R_q:S_q\longrightarrow S_{T(q)}.
\]
Starting from $X_0=e_{q_0}$, fire the reaction belonging to the uniquely represented state. This defines the compiled run $X_0,X_1,\dots$.

\section{Exact finite-trace universality}
Write $T^t$ for the $t$-fold iterate of $T$.

\begin{theorem}[Exact finite-trace simulation]
For every deterministic configuration space $Q$, transition $T:Q\to Q$, initial state $q_0\in Q$, and $t\in\mathbb N$, the compiled run satisfies
\[
 X_t=e_{T^t(q_0)}.
\]
\end{theorem}
\begin{proof}
Induct on $t$. At time zero this is the initialization rule. If $X_t=e_{T^t(q_0)}$, the compiled reaction for $T^t(q_0)$ consumes that unique state molecule and produces one molecule representing $T(T^t(q_0))=T^{t+1}(q_0)$. Hence the result holds at $t+1$.
\end{proof}

A deterministic Turing machine is an instance: $Q$ is its set of instantaneous descriptions, including control state, tape, and head position. Thus every finite Turing-machine execution trace has an exact unary reaction trace. This proves expressiveness, not the laboratory feasibility of an unbounded species family.

\begin{corollary}[Decoded-output preservation]
For any output space $Y$ and decoder $D:Q\to Y$, decoding the represented state at time $t$ gives $D(T^t(q_0))$.
\end{corollary}
\begin{proof}
The represented state is exactly $T^t(q_0)$ by the preceding theorem; apply $D$.
\end{proof}

\begin{corollary}[Halting preservation]
If $h\in Q$ satisfies $T(h)=h$, then a run initialized at $e_h$ satisfies $X_t=e_h$ for every $t\in\mathbb N$.
\end{corollary}
\begin{proof}
Induction gives $T^t(h)=h$ for every $t$, and finite-trace simulation completes the argument.
\end{proof}

\section{Discrete mass-action kinetics}
For $n,m\in\mathbb N$, define the descending factorial by $(n)_0=1$ and
\[
 (n)_m=n(n-1)\cdots(n-m+1)\quad(m>0).
\]

\begin{definition}[Mass-action propensity]
For a reaction $R$ with integer rate $k\geq0$, its discrete stochastic mass-action propensity at $x$ is
\[
 a_R(x)=k\prod_{i\in I}(x(i))_{r_R(i)}.
\]
\end{definition}

\begin{theorem}[Exact source propensity]
For the compiled transition $R_q:S_q\to S_{T(q)}$ evaluated at its one-hot source,
\[
 a_{R_q}(e_q)=k.
\]
\end{theorem}
\begin{proof}
The reactant stoichiometry is one at $q$ and zero elsewhere. The factor at $q$ is $(1)_1=1$, while every other factor is $(0)_0=1$. The product is one.
\end{proof}

\begin{corollary}[Enabledness and positivity]
If $k>0$, then $R_q$ is enabled at $e_q$ and has strictly positive propensity there.
\end{corollary}
\begin{proof}
The source has the one required molecule, and the preceding theorem identifies the propensity with $k$.
\end{proof}

This is a local compatibility result. It does not by itself analyze competing reactions, leakage, diffusion, degradation, or expected completion time in a larger network.

\section{Description capacity and minimum volume}
Let $b$ be reliable bits per integer volume unit, $K$ a description length, and $V$ a volume.

\begin{definition}[Feasibility and minimum volume]
The description fits when
\[
 \operatorname{Fits}(b,V,K)\quad\Longleftrightarrow\quad K\leq bV.
\]
For $b>0$, define
\[
 V_{\min}(b,K)=\left\lceil\frac Kb\right\rceil.
\]
\end{definition}

\begin{theorem}[Minimum volume fits]
If $b>0$, then $K\leq bV_{\min}(b,K)$.
\end{theorem}
\begin{proof}
The ceiling property gives $K/b\leq\lceil K/b\rceil$. Multiply by positive $b$.
\end{proof}

\begin{theorem}[Feasibility--minimality equivalence]
If $b>0$, then for every integer volume $V$,
\[
 V_{\min}(b,K)\leq V\quad\Longleftrightarrow\quad K\leq bV.
\]
\end{theorem}
\begin{proof}
The forward implication follows from the preceding theorem and monotonicity. Conversely, $K\leq bV$ implies $K/b\leq V$. Since $V$ is an integer, the least integer no smaller than $K/b$ is at most $V$.
\end{proof}

\begin{corollary}[Strict minimality]
If $V<V_{\min}(b,K)$, the description does not fit in $V$.
\end{corollary}
\begin{proof}
Feasibility would imply $V_{\min}(b,K)\leq V$, a contradiction.
\end{proof}

\begin{corollary}[Unit-density proportionality]
At one bit per volume unit, $V_{\min}(1,K)=K$.
\end{corollary}
\begin{proof}
Ceiling division by one is the identity.
\end{proof}

This proves an exact proportionality under an explicit unit-capacity model. A two-sided relation to Kolmogorov complexity would require a fixed universal prefix-free language and fabrication conventions with bounded overhead.

\begin{theorem}[Boolean register state count]
A reliable $N$-bit register has exactly $2^N$ Boolean states. In particular, a reliable $10^{18}$-bit register has $2^{10^{18}}$ states.
\end{theorem}
\begin{proof}
Each of $N$ labeled positions independently has two choices, so the multiplication principle gives a product of $N$ factors of two.
\end{proof}

Reliability and independence are part of the premise. Inaccessible states, correlated errors, and ambiguous readout would alter effective capacity.

\section{Preparation-aware molecular parallelism}
Let $N$ be the number of candidate solutions and $c$ the preparation cost per candidate. Normalize one test to one time unit. Define
\[
 T_{\mathrm{seq}}(c,N)=(c+1)N,
 \qquad
 T_{\mathrm{mol}}(c,N)=cN+1.
\]
The first expression prepares and tests candidates sequentially. The second grants perfect parallel testing but charges preparation for every witness.

\begin{theorem}[Preparation lower bound]
For all $c,N\in\mathbb N$,
\[
 cN\leq T_{\mathrm{mol}}(c,N).
\]
\end{theorem}
\begin{proof}
By definition, $T_{\mathrm{mol}}(c,N)=cN+1$.
\end{proof}

\begin{theorem}[Preparation-aware constant-factor bound]
If $c\geq1$, then for every $N$,
\[
 T_{\mathrm{seq}}(c,N)\leq2T_{\mathrm{mol}}(c,N).
\]
\end{theorem}
\begin{proof}
Since $c\geq1$, $c+1\leq2c$. Therefore
\[
 (c+1)N\leq2cN\leq2(cN+1).
\]
These are the stated elapsed times.
\end{proof}

For $N>0$, the speedup is
\[
 \frac{T_{\mathrm{seq}}}{T_{\mathrm{mol}}}
 =\frac{(c+1)N}{cN+1}<\frac{c+1}{c}\leq2.
\]
As $N$ grows it approaches $(c+1)/c$, maximized asymptotically at two when $c=1$.

\begin{corollary}[Exhaustive Boolean search]
For exhaustive search over $n$ Boolean variables and $c\geq1$,
\[
 T_{\mathrm{seq}}(c,2^n)\leq2T_{\mathrm{mol}}(c,2^n).
\]
Consequently, both elapsed times are $\Theta(c2^n)$ for fixed positive $c$.
\end{corollary}
\begin{proof}
Substitute $N=2^n$ in the preceding theorem.
\end{proof}

For $c=1$, representative values are:
\begin{center}
\begin{tabular}{rrrrr}
\toprule
$n$ & $2^n$ & $T_{\mathrm{mol}}$ & $T_{\mathrm{seq}}$ & ratio\\
\midrule
0&1&2&2&1.000\\
1&2&3&4&1.333\\
2&4&5&8&1.600\\
3&8&9&16&1.778\\
4&16&17&32&1.882\\
5&32&33&64&1.939\\
6&64&65&128&1.969\\
7&128&129&256&1.984\\
\bottomrule
\end{tabular}
\end{center}
The exponential test phase has collapsed to one round, but the exponential preparation term remains.

\section{Algorithms}
\paragraph{Trace simulation.}
Given $T$, $q_0$, and horizon $t$, retain the current state and apply $T$ exactly $t$ times. The invariant after $j$ iterations is $q=T^j(q_0)$. Runtime is $O(tC_T)$, where $C_T$ is transition-evaluation cost, and auxiliary storage is one state.

\paragraph{Minimum volume.}
For $b>0$, calculate
\[
 V_{\min}=\left\lfloor\frac{K+b-1}{b}\right\rfloor
\]
with integer arithmetic. This avoids floating-point error. It uses a constant number of arithmetic operations; bit complexity is dominated by division on $O(\log K+\log b)$-bit integers.

\paragraph{Parallelism comparison.}
Given $c$ and $N$, calculate $cN+1$ and $(c+1)N$. For Boolean search first set $N=2^n$. Exact arbitrary-precision arithmetic exposes both the exponential scale and the bounded speedup ratio.

\section{Applications and interpretation}
The trace theorem supplies reference semantics for molecular controllers, protocol state machines, and encoded Turing computations. Practical compilation should reduce species count, use bounded molecular populations, restrict molecularity, and tolerate stochastic errors.

The volume law applies to any substrate once a defensible effective bit density is supplied. DNA bases, conformations, magnetic domains, and other media differ in density, addressing, redundancy, and readout overhead, not in the ceiling arithmetic that follows from an accepted capacity.

Molecular systems can evaluate many Boolean assignments concurrently. The preparation-aware bound shows why reaction depth alone is not an end-to-end complexity measure. If every assignment requires a separately prepared witness, exhaustive satisfiability search remains exponential. Asymptotic improvement would require shared or compressed witness generation, a non-exhaustive algorithm, or different resource accounting.

Claims about $10^{18}$ bits per cubic micrometre or $10^{15}$ operations per second must specify temperature, duration, error correction, read/write protocol, energy and material inputs, and the definition of a logical operation. The mathematics states what follows if these premises hold; experiments determine whether they do.

\section{Limitations and future work}
The universality compiler uses one species per configuration and may therefore be physically extravagant or infinite. The propensity theorem is local and excludes races and side reactions. The storage model assumes independent reliable bits. The preparation model explicitly charges $cN$ and must be replaced if a defensible physical process generates witnesses with different accounting.

Five directions are immediate. First, construct finite bimolecular compilers with fixed controller overhead and quantitative stochastic completion guarantees. Second, use redundant encodings and majority decoding to prove exponentially decreasing trace error below a one-half component failure threshold. Third, fix a universal prefix-free reaction-network language and fabrication model to derive a two-sided volume law in terms of Kolmogorov complexity. Fourth, combine one-witness-per-assignment requirements with bounded preparation throughput $R$ to derive a $2^n/R$ elapsed-time lower bound. Fifth, test DNA capacity and sustained error-corrected throughput simultaneously under a declared physical protocol.

\section{Conclusion}
Chemical reaction networks reproduce arbitrary deterministic computation at the level of exact finite traces. At a one-hot source, a compiled unary transition has mass-action propensity equal to its assigned rate. A $K$-bit description at positive density $b$ has exact minimum integer volume $\lceil K/b\rceil$. Perfect molecular parallel testing, when accompanied by linear per-candidate preparation, gives at most a factor-two end-to-end advantage over sequential exhaustive search.

Universality is a statement about expressiveness; density and throughput are conditional on measurement; complexity depends on complete resource accounting. This separation clarifies both the promise and the limits of molecular computation.
\end{document}

