#!/usr/bin/env python3
from typing import Callable, Hashable, List, TypeVar
S = TypeVar("S", bound=Hashable)
def trace(step: Callable[[S], S], initial: S, count: int) -> List[S]:
    if count < 0: raise ValueError("count must be nonnegative")
    out = [initial]
    for _ in range(count): out.append(step(out[-1]))
    return out
if __name__ == "__main__":
    transitions = {"scan":"copy", "copy":"check", "check":"halt", "halt":"halt"}
    result = trace(transitions.__getitem__, "scan", 7)
    assert result == ["scan","copy","check","halt","halt","halt","halt","halt"]
    print(" -> ".join(result))

#!/usr/bin/env python3
def minimum_volume(density: int, bits: int) -> int:
    if density <= 0 or bits < 0: raise ValueError("positive density and nonnegative bits required")
    return (bits + density - 1) // density
if __name__ == "__main__":
    for bits, density in [(1,8),(8,8),(9,8),(1000,64),(10018,1000)]:
        volume = minimum_volume(density, bits)
        assert bits <= density * volume
        assert volume == 0 or density * (volume - 1) < bits
        print(f"K={bits:5d}, b={density:4d}, minimum V={volume}")

#!/usr/bin/env python3
def times(cost: int, variables: int) -> tuple[int, int]:
    if cost < 1 or variables < 0: raise ValueError("cost >= 1 and variables >= 0 required")
    candidates = 1 << variables
    return cost * candidates + 1, (cost + 1) * candidates
if __name__ == "__main__":
    for n in range(13):
        molecular, sequential = times(1, n)
        assert sequential <= 2 * molecular
        print(f"n={n:2d}, molecular={molecular:5d}, sequential={sequential:5d}, ratio={sequential/molecular:.5f}")

